{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C269", "C276", "C246", "C330", "C296", "C289", "C302", "C320"],
  "contradictory_card_ids": ["C321", "C323"],
  "prediction_basis_card_ids": ["C269", "C276", "C246", "C330", "C296", "C289", "C302"],
  "claims": [
    {
      "claim": "C269: a cinnamohydroxamic acid HDAC inhibitor bearing a secondary amine (10p) showed low Caco-2 absorptive permeability (Papp A→B 0.97×10^-6 cm/s) and marked efflux (ER 10.8), attributed to the secondary amine; this is the closest analog to the query's secondary-amine cinnamohydroxamic acid scaffold.",
      "card_ids": ["C269"]
    },
    {
      "claim": "C276: the hydroxamic acid DPC333 was a P-gp substrate with intestinal clearance of 0.2–0.35 L/h/kg and ~20% of an IV dose recovered in the lumen, showing that hydroxamic acids can undergo substantial gut-wall efflux/excretion.",
      "card_ids": ["C276"]
    },
    {
      "claim": "C330: compound 5d, a cinnamohydroxamic acid, had high human liver microsomal intrinsic clearance (105.06 µL/min/mg), indicating extensive hepatic metabolism of this warhead.",
      "card_ids": ["C330"]
    },
    {
      "claim": "C296: a cinnamoyl compound with a basic polyamine (compound 2) had HLM t1/2 35.7 min and calculated hepatic extraction 0.61, supporting high first-pass for cinnamoyl basic amines.",
      "card_ids": ["C296"]
    },
    {
      "claim": "C289: KW-2449, a cinnamoyl piperazine, had predicted human hepatic clearance 0.741 L/h/kg, consistent with substantial presystemic hepatic loss.",
      "card_ids": ["C289"]
    },
    {
      "claim": "C321 and C323 provide some counter-evidence (acceptable HLM stability for compound 5d; low UGT1A1 CLint for belinostat), but they are outweighed by the direct high-CLint and efflux records and do not establish F≥20%.",
      "card_ids": ["C321", "C323"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C330", "C296", "C289", "C302", "C320"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query or an exact analog.",
    "No matched oral vs IV AUC for the query scaffold.",
    "L6 hepatic clearance records are in vitro/predicted and from analogs, not direct F results.",
    "Transfer from benzimidazole/pyridine cinnamohydroxamic acids to the indole query is uncertain.",
    "Dose, formulation, and saturation of efflux/metabolism are unknown.",
    "Conflicting metabolic-stability records for compound 5d (C321 vs C330) are unresolved."
  ],
  "decision_summary": "L6 adds hepatic-clearance evidence that strengthens the L5 low prediction: a cinnamohydroxamic acid analog (compound 5d) had high HLM intrinsic clearance (C330), a cinnamoyl basic polyamine had calculated hepatic extraction 0.61 (C296), and a cinnamoyl piperazine had predicted hepatic clearance 0.741 L/h/kg (C289). Combined with the query's very low neutral fraction and the L5 secondary-amine efflux evidence (C269, C276, C246), the coherent mechanistic picture supports F < 20%."
}

